package com.csust.eyediagnosis.workflow.persistence.repository;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.csust.eyediagnosis.workflow.persistence.entity.WorkflowNodeExecutionEntity; import com.csust.eyediagnosis.workflow.persistence.mapper.WorkflowNodeExecutionMapper; import org.springframework.stereotype.Repository; import java.util.Optional;
@Repository public class MybatisNodeExecutionRepository implements NodeExecutionRepository { private final WorkflowNodeExecutionMapper mapper; public MybatisNodeExecutionRepository(WorkflowNodeExecutionMapper mapper){this.mapper=mapper;} public int insertIfAbsent(WorkflowNodeExecutionEntity e){return mapper.insert(e);} public Optional<WorkflowNodeExecutionEntity> findByIdempotencyKey(String key){return Optional.ofNullable(mapper.selectOne(new LambdaQueryWrapper<WorkflowNodeExecutionEntity>().eq(WorkflowNodeExecutionEntity::getIdempotencyKey,key)));} }
